36	static int velaguard_ui_main(int argc, FAR char *argv[])
37	{
38	  lv_nuttx_dsc_t info;
39	  lv_nuttx_result_t result;
40	
41	  UNUSED(argc);
42	  UNUSED(argv);
43	
44	  lv_init();
45	  lv_nuttx_dsc_init(&info);
46	  info.input_path = CONFIG_LVX_VELAGUARD_INPUT_PATH;
47	  lv_nuttx_init(&info, &result);
48	  if (result.disp == NULL)
49	    {
50	      fprintf(stderr, "[velaguard] LVGL display initialization failed\n");
51	      lv_nuttx_deinit(&result);
52	      lv_deinit();
53	      return 1;
54	    }
55	
56	  if (result.indev == NULL)
57	    {
58	      fprintf(stderr,
59	              "[velaguard] touchscreen unavailable; home remains visible\n");
60	    }
61	
62	  vg_ui_home_create();
63	  printf("[velaguard] UI ready\n");
64	
65	  while (true)
66	    {
67	      uint32_t idle = lv_timer_handler();
68	
69	      if (idle < 1)
70	        {
71	          idle = 1;
72	        }
73	      else if (idle > 100)
74	        {
75	          idle = 100;
76	        }
77	
78	      usleep(idle * 1000);
79	    }
80	}
